/**
 * Nitro plugin that turns Cloudflare Cron Triggers into internal calls to the alert hooks.
 *
 * The deployed Worker entry is generated by Nitro (src/server.ts is only the TanStack Start
 * SSR entry behind it), so a bare `scheduled` export on server.ts would never be invoked.
 * Nitro forwards the Worker `scheduled` event to the `cloudflare:scheduled` runtime hook; we
 * answer it here by dispatching POSTs straight into the app's own fetch handler (no network
 * hop), authenticated with the CRON_SECRET Worker secret.
 *
 * Registered in vite.config.ts via `nitro.plugins`. Cron expressions live in
 * src/lib/cron-schedule.ts and wrangler.jsonc (kept in sync by a unit test).
 */
import { definePlugin } from "nitro";

import { appUrl } from "../lib/app-url";
import { runCronHooks } from "../lib/cron-schedule";

type ScheduledPayload = {
  controller: { cron: string };
  env: Record<string, unknown> | undefined;
};

export default definePlugin((nitroApp) => {
  // `cloudflare:scheduled` is added to the hook map by the cloudflare preset's type augmentation,
  // which is not visible to the app's tsconfig - register via the untyped hookable signature.
  (
    nitroApp.hooks as unknown as {
      hook: (name: string, fn: (p: ScheduledPayload) => unknown) => void;
    }
  ).hook("cloudflare:scheduled", async ({ controller, env }) => {
    const fromEnv = env?.CRON_SECRET;
    const secret =
      typeof fromEnv === "string" && fromEnv ? fromEnv : (process.env.CRON_SECRET ?? undefined);
    await runCronHooks(controller.cron, {
      secret,
      urlFor: (path) => appUrl(path),
      dispatch: (request) => nitroApp.fetch(request),
    });
  });
});
